INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_a90986008accfc60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_parliament', 'Article 35 A was abrogated by Modi Government on 5th August 2019 to indulge in?', '{"A":"Demographic engineering","B":"Conduct of Plebiscite","C":"Ending warfare","D":"Respecting International Law"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 35A was revoked on 5 August 2019 by the Government of India.The move was widely viewed as enabling demographic changes in Kashmir.It removed special rights related to residency and property ownership.The decision was linked with revocation of Article 370.It created significant political and regional tensions.Last verified on 29-04-2026', 0, 0, 0, 1790969780100) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_4ce2788c339e2dca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_parliament', 'Who is the current leader of the opposition in the Senate of Pakistan?', '{"A":"Shibli Faraz","B":"Raja Nasir Abbas","C":"Yousaf Raza Gillani","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Raja Nasir Abbas is the current leader of the opposition in the Senate of Pakistan since 2026.He is the chief of Majlis Wahdat-i-Muslimeen (MWM).He replaced Shibli Faraz who was disqualified in August 2025.Last Updated on 20-01-2026.', 0, 0, 0, 1790969780100) ON CONFLICT(id) DO NOTHING;
