INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_7cb1a781781f5ec2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_parliament', 'Who is the current deputy Speaker of Azad Jammu and Kashmir (AJK) Legislative Assembly?', '{"A":"Asim Bajwa","B":"Ch. Riaz Gujjar","C":"Omar Ayub Khan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Riaz Ahmed of the Pakistan Tehreek-i-Insaf (PTI) were elected deputy speaker of the Azad Jammu and Kashmir (AJK) LegislativeAssembly, on August 3, 2021. He defeated Nisara Abbasi of the Pakistan Muslim League-Nawaz (PML-N) by securing 32 votes against 15 of his opponents.', 0, 0, 0, 1790969780131) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_ad809729fb212fe9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_parliament', 'Who is the current Leader of the House of Azad Jammu and Kashmir (AJK) Legislative Assembly?', '{"A":"Abdul Qayyum Khan Niazi","B":"Choudhary Muhammad Yasin","C":"Sardar Attique Ahmed Khan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abdul Qayyum Khan Niaz (PTI) is the current Leader of the House of Azad Jammu and Kashmir (AJK) Legislative Assembly Since 04.08.2021', 0, 0, 0, 1790969780131) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_db709d20eab15ab7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_parliament', 'Who is the first Pakistani Prime Minister to face a vote of confidence in the National Assembly after 18th Amendment?', '{"A":"Nawaz Sharif","B":"Yousuf Raza Gilani","C":"Imran Khan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prior to this, the law required every prime minister to take a vote of confidence from the Assembly within 30 days of being elected.Since 2010, however, the law does not require such a practice. In fact, according to clause 7 of Article 91 of the Constitution, the president “shall not exercise his powers under this clause unless he is satisfied that the prime minister does not command the confidence of the majority” in the Assembly. This is the first time a prime minister has undertaken such an exercise after the passage of the 18th Amendment.', 0, 0, 0, 1790969780131) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_5e9d48dc5bcb0151', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_parliament', 'Who is the highest tax paid member of National Assembly of Pakistan for the year 2020___?', '{"A":"Nawaz Sharif","B":"Imran khan","C":"Shahbaz Sharif","D":"Shahid Khaqan Abbasi"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shahid Khaqan Abbasi paid Rs241 million in an individual capacity in the year 2018.Prime Minister Imran Khan''s paid tax Rs 282,449. Leader of the Opposition Shehbaz Sharif paid Rs9 million 2018.PPP chief Bilawal Bhutto-Zardari paid Rs294,117 in 2018. PPP co-chairperson Asif Ali Zardari paid Rs2.8 million taxes in 2018.', 0, 0, 0, 1790969780141) ON CONFLICT(id) DO NOTHING;
