INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_9194c79120e8978a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_defense', 'Who is the Current Defence Minister of Pakistan?', '{"A":"Khawaja Muhammad Asif","B":"Azam Nazeer Tarar","C":"Musadik Masood Malik","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The current Minister for Defence of Pakistan is Khawaja Muhammad Asif.Sworn in in March 2024He replaced Anwar Ali HaiderPreviously served in the post from 2013 to 2017. He has been a Member of the National Assembly from Sialkot since 1993Elected for the seventh time in 2024Question updated 03-March-2026 Click here for reference', 0, 0, 0, 1790969780162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_4508b1dc729bd126', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_defense', 'Who is the current Chief of Air Staff (Marshal)?', '{"A":"Mujahid Anwar Khan","B":"Zaheer Ahmad Babar","C":"Amanullah Ahsan","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Air Chief Marshal Zaheer Ahmad Babar Sidhu 23rd Chief of Air Staff (CAS) of the Pakistan Air Force.He assumed office on 19 March 2021.He replaced Air Chief Marshal Mujahid Anwar Khan.He joined PAF in 1986 as a fighter pilot (GD Pilot branch).He belongs to Sidhar, Gujrat (Punjab).Last updated 17 july 2026 by NA', 0, 0, 0, 1790969780162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_3b100223e09bf361', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_defense', 'Pakistan successfully conducted flight test of ________ weapon system in October 2023.', '{"A":"Shaheen III","B":"Ababeel","C":"Abdali","D":"Zarb"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan conducted a successful test of the Ababeel missile system in October 2023.According to Inter-Services Public Relations (ISPR), the test was successful.Ababeel is a multiple independently targetable reentry vehicle (MIRV) missile.Its name means “Flock of Birds” in Arabic.Last verified on 29-04-2026', 0, 0, 0, 1790969780162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_53440b57b6300f8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_defense', 'Who is the current federal minister for defence production in Pakistan?', '{"A":"Muhammad Junaid Anwar","B":"Ali Pervaiz Malik","C":"Muhammad Raza Hayat Harraj","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muhammad Raza Hayat Harraj is the current Federal Minister for Defence Sworn in on 07 March 2025 Updated on 07 March 2025 Click here for reference Last updated by NA on 25-April-2026', 0, 0, 0, 1790969780162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_38b0d2d3772e6f21', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_defense', 'Who is the current Chief of Naval Staff of Pakistan?', '{"A":"Admiral Waseem Akram","B":"Admiral Naveed Ashraf","C":"Admiral Mujahid Anwar Khan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Admiral Naveed Ashraf, NI(M) is the current Chief of the Naval Staff of the Pakistan Navy.Term length of 3 years (Renewable only once)Replace: Admiral M Amjad Khan Niazi 23rd Chief of the Naval Staff (CNS) (18+5 = 23)Since October 2023Last updated on 05-04-2026', 0, 0, 0, 1790969780162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_7ed13ea086a77c8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_defense', 'Who is the Current DG ISPR of Pakistan Army?', '{"A":"Major General Babar Iftikhar","B":"Major General Asif Ghafoor","C":"Major General Ahmed Sharif Chaudhry","D":"Lt General Asim Saleem Bajwa"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Major General Ahmed Sharif Chaudhry becomes new DG ISPR in December 2022.Previously, Major general Babar Iftikhar was serving as DG ISPR.update on 19 august 2024', 0, 0, 0, 1790969780162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_6162253bfde6d3c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_defense', 'Who is the Current Chief of Air Staff of Pakistan Air Force (PAF)?', '{"A":"Air Marshal Sohail Aman","B":"Air Marshal Mujahid Anwar Khan","C":"Air Marshal Zaheer Ahmad Babar","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Air Marshal Zaheer Ahmad Babar, is the 23rd and the current Chief of Air Staff of the Pakistan Air Force since 19 March 2021, he replace Mujahid Anwar Khan . Zaheer Ahmad Babar joined the force in 1986 as a fighter pilot He belongs to Sidh, Gujrat.', 0, 0, 0, 1790969780162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_d674031772a7da6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_defense', 'The Police Martyrs Day is observed on which date in Pakistan?', '{"A":"August 6","B":"August 4","C":"August 2","D":"August 1","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Police Martyrs Day is observed on August 4th across Pakistan to honor the services of the police department.It marks the death anniversary of Shaheed Safwat Ghayur.He was martyred in a suicide attack on August 4th, 2010.', 0, 0, 0, 1790969780162) ON CONFLICT(id) DO NOTHING;
