INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_969bdcfdc2406cdf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_economy', 'What is the current SBP interest rate in Pakistan?', '{"A":"11.5 percent","B":"12.5 percent","C":"13.5 percent","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The current State Bank of Pakistan (SBP) policy interest rate is 11.5%, effective since September 2026. 1 percent was increased on 26 April 2026. The 11% rate mentioned was the previous benchmark, which was held steady from June to October 2025. ***Verified & updated on 20-09-2026', 0, 0, 0, 1790969780205) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_03c6386bb47d5385', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_economy', 'Who is the Current Governor of the State Bank of Pakistan (SBP)?', '{"A":"Dr Reza Baqir","B":"Tariq Bajwa","C":"Jameel Ahmed","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Jameel AhmadTerm: 5 years, 19 August 2022Previously, Murtaza Syed ======History of State BankThe President of Pakistan appoints the Governor.Term of five years.Zahid Husain was the founder and the first governor of the State Bank of Pakistan from June 1948 to July 1953.Dr. Shamshad Akhtar became the first female Governor of State Bank of Pakistan in 2006.Last updated by NS on 06 May 2026', 0, 0, 0, 1790969780205) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_44f13239665cec54', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_economy', 'The dam inaugurated in October 2020 by the Sindh Government in Nagarparkar, District Tharparkar, was?', '{"A":"Kalidas Dam","B":"Sohan Dam","C":"Ningharahr Dam","D":"Dasu Dam"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dam Name: Kalidas DamLocation: Nagarparkar, Tharparkar, SindhInauguration Date: 29 October 2020Cost: Rs. 333 millionPurpose: Water storage and supplyAdditional information:Dams completed by Sindh Government at that time: 23Additional dams under construction: 11Expected completion of those dams: by July 2022Last verified on 11-06-2026', 0, 0, 0, 1790969780205) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_61e8f9409b1841d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_economy', 'On 15 February 2022, State Bank of Pakistan launched Raast ___________ instant payments system.', '{"A":"System to person","B":"Person to person","C":"System to system","D":"Person to system"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The then prime Minister Imran Khan 15-02-2022 launched the country’s first instant person-to-person payment system ‘Raast’ for low-cost digital retail payments and money transfers.whileon 11th January 2021, PM Imran Khan unveiled RAAST''s first instant payment system to increase Financial inclusion and eliminate corruptionNA23-7-2023', 0, 0, 0, 1790969780205) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_5a712be45d2e4e68', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_economy', 'Which of the following court unfreezes PIA assets in the Reko Diq award case?', '{"A":"International Court of Justice","B":"International Court of Justice","C":"British Virgin Islands High court","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The British Virgin Islands High Court has ordered unfreezing offshore assets of the Pakistan International Airlines in the Reko Diq case on May 25, 2021. The court has recalled its December 2020 orders to attach certain PIA assets in the Reko Diq case against Pakistan.', 0, 0, 0, 1790969780205) ON CONFLICT(id) DO NOTHING;
