INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_192ad5baff2d9fe1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_foreign', 'FATF decided to keep Pakistan on grey list until __________?', '{"A":"April 2021","B":"June 2021","C":"August 2021","D":"December 2021"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On June 2018 FATF added Pakistan to its gray listPakistan needs 12 votes out of 39 to exit the “grey" list and move up to join countries that do not require monitoring. Pakistan has been removed from the list after four years n 21 October 2022 on Thursday FATF decided to retain Pakistan on its ‘Grey List’ till June 2021**while On 24 February 2023, FATF added South Africa and Nigeria to its gray listOn 24 February 2023, FATF removed Cambodia and Morocco from its gray listND7-5-2023', 0, 0, 0, 1790969780332) ON CONFLICT(id) DO NOTHING;
