INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_b612a56779521065', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_sports', 'Which Pakistani mountaineer becomes first Asian to summit Mount Kilimanjaro within 24 hours?', '{"A":"Asad Ali Memon","B":"Muhammad Ali Sadpara","C":"Sajid Ali Sadpara","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ø Asad Ali Memon says it took him 20 hours to complete summit and return to gate of Mount Kilimanjaro.Ø Pakistani mountaineer Asad Ali Memon on 17-02-2021 became the first Pakistani and Asian to summit the Mount Kilimanjaro within 24 hours. Ø Mount Kilimanjaro is a dormant volcano in Tanzania. Ø It is the highest mountain in Africa and Ø The highest single free-standing mountain in the world. Ø Height 5,895 metros', 0, 0, 0, 1790969780407) ON CONFLICT(id) DO NOTHING;
