INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_67e2b2c525f70a96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_general', 'Which country has provided 12 T16 high-tech drones to help Pakistan combating locusts?', '{"A":"China","B":"UAE","C":"UK","D":"USA"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation China has provided 12 T16 high-tech farm drones to Pakistan to help combat locusts. China will also send technical support staff to operate the drones and train local operators. The operator can control five drones at the same time without actually being on the field.', 0, 0, 0, 1790969781281) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_055b48b75f5d1ccf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_general', 'PTA issues notice to _________ for ''disseminating sacrilegious content'' on 25 Dec, 2020:', '{"A":"Google, Wikipedia","B":"Google, YouTube","C":"Facebook, YouTube","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pakistan Telecommunication Authority (PTA) has issued notices to Google Inc and Wikipedia for "disseminating sacrilegious content" "The platform has been issued the notice under the Removal and Blocking of Unlawful Online Content (Procedure, Oversight and Safeguard) Rules 2020 to remove sacrilegious content to avoid any legal action by the regulator."', 0, 0, 0, 1790969781281) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_c0468a17856d6995', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_general', 'Pakistan has found new deposits of oil and gas in exploratory well Mamikhel South-01, located in Tal block in__________?', '{"A":"KPK","B":"Punjab","C":"Sindh","D":"none of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan Oilf­i­elds Ltd (POL) reported hyd­r­ocarbons discovery in exploratory well in Tal block, Mamikhel South-01 Khyber Pakhtoonthwa.The company holds 21 per cent stake in the Tal Block, while the Ola and Gas and Development Company and Pakistan Petroleum own 27.8pc each. MOL is the operator of the block with 8.4pc interest.', 0, 0, 0, 1790969781281) ON CONFLICT(id) DO NOTHING;
