INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tpa_936ac6e43fe5e8dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pa_general', 'A new tourist site has recently been inaugurated in which city?', '{"A":"Islamabad","B":"Karachi","C":"Lahore","D":"Multan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The city managers have developed a new tourist site having a lotus lake near the natural history museum.Capital Development Authority (CDA) Chairman Amer Ali Ahmed on November 22, 2020 inaugurated the site which will be known as `Family Park`.', 0, 0, 0, 1790969781298) ON CONFLICT(id) DO NOTHING;
